  ('sugarbush-mad-river-glen-vermont', '12A', 'Sugarbush (+ Mad River Glen)', 'United States', 'Two mountains on the Ikon Pass', 'live', 'verified', 'northernLights', 'New England', '{"ski","romance","culinary","family"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, 'emerging', '{"key_facts":["Sugarbush = two mountains (Lincoln Peak summit ~3,975 ft + Mount Ellen ~4,083 ft, tied third-highest in Vermont) linked by the Slide Brook Express quad; ~111 trails + 18 wooded areas, ~484 skiable trail acres, 16 lifts","Alterra Mountain Company acquired Sugarbush Nov 2019 (its 15th destination); on the Ikon Pass (full 7 days, Base 5 days w/ blackouts)","Slopeside Clay Brook Hotel & Residences (opened 2006) at the Lincoln Peak base village","FOLDED IN — Mad River Glen: skier-owned cooperative (formed Dec 5, 1995 — only one in America); bans snowboarders; famed Single Chair (first ran 1948, rebuilt 2007 — last single-seat chairlift in the US); natural-snow/largely ungroomed expert terrain on General Stark Mountain; slogan ''Ski It If You Can''; NO bundle pass (independent)","Valley base Waitsfield + Warren — the Pitcher Inn (Relais & Chateaux, Warren, member since 1997, 12 rooms, restaurants 275 Main + Tracks) + the ''almost world famous'' Warren Store","Central Vermont Medical Center (Berlin, 24/7 ER, UVM Health Network) nearest hospital; access via I-89 + VT-100 / VT-17 (Appalachian Gap)"],"safety":{"emergency":"911 (police/fire/ambulance/rescue dispatch, nationwide)","hospital":"Central Vermont Medical Center (Berlin, 24/7 ER, UVM Health Network, ~30-40 min from the Mad River Valley); serious cases to UVM Medical Center Burlington","malaria":"none","yellow_fever":"not required","activity_note":"ICE/HARDPACK + FREEZE-THAW (defining Eastern condition — boilerplate/blue ice/loss-of-edge; amplified on Mad River Glen''s natural ungroomed terrain); EXTREME COLD + WIND-CHILL (exposed ridgelines + slow open Single Chair — frostbite fast); Vermont winter driving (I-89 + VT-100/VT-17 Appalachian Gap steep/closed in snow; 511VT); avalanche LOW in-bounds (shallow Eastern snowpack, no daily forecast product) but not none in backcountry; tree wells de-emphasized (shallow snowpack); natural/ungroomed terrain hazards at Mad River Glen (rocks, stumps, waterbars, tight trails)","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/usa","read":"2026-08-20T14:47:42Z","page_updated":"2026-08-18T10:29:04+01:00","source_country":"usa","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely"},"timing":{"peak":"High winter (Christmas/NY, MLK + Presidents'' wknds, Feb) + strong weekend peaks (Boston/NY/Montreal drive market); natural-snow cycles (Mad River Glen)","shoulder":"early season (mid-late Dec), Jan weekdays, March spring corn","green":"Apr-May + late Oct-early Dec (between-season lulls; Mad River Glen + upper terrain close with natural snow — verify)","booking_lead":"Christmas/NY + Pitcher Inn/Clay Brook 4-9 mo; Presidents''/Feb 2-5 mo; March/shoulder 2-8 wk; powder days 1-2 wk (weekend drive-in Northeast/Montreal market)","off_season_specials":"March spring-corn ski deals; summer + fall foliage valley (late Sep-mid Oct); midweek ski value; culinary + inn weekends as shoulder engine","event_peaks":"Christmas/NY, MLK + Presidents'' wknds, US school half-terms, fall foliage (late Sep-mid Oct), spring closing/pond-skim (verify 2027)","fire_date":"FIRE ski mid-late Mar (ahead of Apr-Jun early-bird) + late Aug-early Sep (ahead of Sep-Nov fall wave); market summer/foliage valley by mid-summer"},"jewels":[{"name":"Ski two mountains on one resort — Lincoln Peak + Mount Ellen","si_tag":"Winter / Ski","status":"future","tier":"comfort","price_band":"~USD 89-169/day lift; package higher","timing":"ski ~late Dec-Mar, snow-dependent; in-bounds patrolled","draw_rank":1,"hook":"ride the Slide Brook Express between Sugarbush''s two peaks","si":"s